'use strict';
// Test-only measured next terminal. This data creates no worker/owner authority.
const fs=require('fs'),path=require('path'),crypto=require('crypto'),zlib=require('zlib'),assert=require('node:assert/strict');
const layer=require('./distribution-delta.json'),previous=require('../owner-recovery/distribution.cjs');
const ROOT=path.resolve(__dirname,'../../..');
const SPEC=(()=>{const bytes=zlib.gunzipSync(Buffer.from('','base64'),{maxOutputLength:4*1024*1024});assert.equal(bytes.length,183980);assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),'879c0f25850b79002f06923c640bc2ce882a68f8c0cdcb7687cd18575330994a');return JSON.parse(bytes);})();
const hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const linked=/^<!-- forge:linked-task:([a-z0-9-]+):start -->\r?\n[\s\S]*?^<!-- forge:linked-task:\1:end -->\r?\n/gm;
const normalize=text=>String(text).replace(/version=\d+\.\d+\.\d+/g,'version=<dynamic>');
const read=file=>fs.readFileSync(path.join(ROOT,file));
const attributed=bytes=>hash(bytes.toString('utf8').replace(linked,''));
const decode=row=>zlib.gunzipSync(Buffer.from(row.before_gzip_base64,'base64'),{maxOutputLength:4*1024*1024});
const artifactKey=item=>item.source_id+'::'+item.source;
function predecessorRead(readRaw,file,value=layer){
 const row=value.files[file];if(!row||row.before===null)return readRaw(file);
 const bytes=decode(row);assert.equal(hash(bytes),SPEC.files[file].before,'#382 exact parent source '+file);return bytes;
}
function predecessorArtifacts(artifacts,value=layer){return artifacts.map(item=>{
 const row=value.rendered[artifactKey(item)];if(!row)return item;
 const content=decode(row).toString('utf8');assert.equal(hash(normalize(content)),SPEC.rendered[artifactKey(item)].before);
 return{...item,content,...(Object.hasOwn(item,'bytes')?{bytes:Buffer.byteLength(content)}:{})};
});}
function measure(artifacts,id,attr=false){return hash(artifacts.filter(item=>item.source_id===id).sort((a,b)=>a.source.localeCompare(b.source)).map(item=>item.source+'\0'+normalize(attr?item.content.replace(linked,''):item.content)).join('\0'));}
function projectRegistry(rows,value=layer){
 assert(value.registry&&typeof value.registry==='object'&&!Array.isArray(value.registry));
 assert.deepEqual(Object.keys(value.registry).sort(),['before_count','after_count','before_sha256','after_sha256','before_rows','after_rows'].sort());
 assert.deepEqual(value.registry,SPEC.registry,'#382 independent full registry pin');
 for(const side of ['before','after']){assert.equal(value.registry[side+'_count'],254);assert.equal(value.registry[side+'_rows'].length,254);assert.equal(hash(JSON.stringify(value.registry[side+'_rows'])),value.registry[side+'_sha256']);}
 assert.deepEqual(value.registry.before_rows,value.registry.after_rows,'#382 no scanner or classification rewrite');
 assert.deepEqual(rows,value.registry.after_rows,'#382 exact current254; missing/extra/reclassified rows refuse');
 return structuredClone(value.registry.before_rows);
}
function previousRegistry(rows,value=layer){return previous.previousRegistry(projectRegistry(rows,value));}
function validateOwn({artifacts,readRaw,value}){
 assert.deepEqual(Object.keys(value).sort(),['schema_version','issue','kind','provenance','files','rendered','surfaces','unchanged_surfaces','samples','registry','control_doc'].sort());
 assert.equal(value.schema_version,1);assert.equal(value.issue,382);assert.equal(value.kind,'request-retention-measured-next-terminal');
 assert.deepEqual(value.provenance,SPEC.provenance,'#382 pinned public parent and data-only bounded provenance');
 for(const key of ['files','rendered','surfaces'])assert.deepEqual(Object.keys(value[key]),Object.keys(SPEC[key]),'#382 closed '+key);
 assert.deepEqual(value.unchanged_surfaces,SPEC.unchanged_surfaces);assert.deepEqual(artifacts.map(artifactKey).sort(),SPEC.members);
 const current=require(path.join(ROOT,'scripts/forge-dispatch-source-guard.js')).SOURCE_REGISTRY;
 assert.equal(previousRegistry(current,value).length,248,'#382 preserved254->252->248 chain');
 assert.equal(previous.ownerRecoveryLayer.registry.before_count,252);assert.equal(previous.ownerRecoveryLayer.registry.after_count,254);
 const nativeLayer=require('../native-effort/distribution.cjs'),nativeNode=nativeLayer.nativeEffortLayer.registry,canonical252=previous.ownerRecoveryLayer.registry.before_rows;
 assert.deepEqual(Object.keys(nativeNode).sort(),['before_count','after_count','before_sha256','after_sha256','before_rows'].sort());
 assert.equal(nativeNode.before_count,248);assert.equal(nativeNode.after_count,252);assert.equal(canonical252.length,252);
 assert.equal(hash(JSON.stringify(canonical252)),nativeNode.after_sha256,'#382 actual native252 postimage SHA');
 assert.equal(previous.ownerRecoveryLayer.registry.before_sha256,nativeNode.after_sha256);
 const canonical248=nativeLayer.previousRegistry(canonical252);assert.equal(canonical248.length,248);assert.equal(hash(JSON.stringify(canonical248)),nativeNode.before_sha256);assert.deepEqual(canonical248,nativeNode.before_rows);
 assert.deepEqual(previousRegistry(current,value),canonical248,'#382 exact composed registry chain');
 for(const[file,pin]of Object.entries(SPEC.prior_pins))assert.equal(hash(readRaw(file)),pin,'#382 immutable prior source '+file);
 for(const[file,expected]of Object.entries(SPEC.files)){
  const row=value.files[file];assert.deepEqual(Object.keys(row).sort(),['before','after','attributed_before','attributed_after','before_gzip_base64'].sort());
  for(const field of ['before','after','attributed_before','attributed_after'])assert.equal(row[field],expected[field],'#382 independent '+field+' '+file);
  const actual=readRaw(file);assert.equal(hash(actual),expected.after,'#382 measured source '+file);assert.equal(attributed(actual),expected.attributed_after);
  if(expected.before===null)assert.equal(row.before_gzip_base64,null);else{const bytes=decode(row);assert.equal(hash(bytes),expected.before);assert.equal(attributed(bytes),expected.attributed_before);}
 }
 for(const[key,expected]of Object.entries(SPEC.rendered)){
  const row=value.rendered[key],item=artifacts.find(item=>artifactKey(item)===key);
  assert.deepEqual(Object.keys(row).sort(),['source_id','source','before','after','attributed_before','attributed_after','before_gzip_base64'].sort());
  for(const field of ['source_id','source','before','after','attributed_before','attributed_after'])assert.equal(row[field],expected[field],'#382 independent rendered '+field);
  assert.equal(hash(normalize(item.content)),expected.after);assert.equal(hash(normalize(item.content.replace(linked,''))),expected.attributed_after);
  assert.equal(hash(normalize(decode(row).toString('utf8'))),expected.before);
 }
 for(const[id,pin]of Object.entries(SPEC.surfaces)){assert.deepEqual(value.surfaces[id],pin);assert.equal(measure(artifacts,id),pin.after);assert.equal(measure(artifacts,id,true),pin.attributed_after);}
 for(const[id,pin]of Object.entries(SPEC.unchanged_pins)){assert.equal(measure(artifacts,id),pin.before);assert.equal(measure(artifacts,id,true),pin.attributed_before);}
 assert.deepEqual(value.samples,SPEC.samples,'#382 exact existing citation pointers');
 const text=readRaw(value.samples.file).toString('utf8'),prior=predecessorRead(readRaw,value.samples.file,value).toString('utf8');
 const data=JSON.parse(text),mappings=new Map();
 for(const row of value.samples.nodes){assert.equal(row.pointer.split('/').slice(1).reduce((v,k)=>v[k],data),row.after);if(mappings.has(row.after))assert.equal(mappings.get(row.after),row.before);mappings.set(row.after,row.before);}
 let restored=text;for(const[after,before]of mappings){const count=value.samples.nodes.filter(row=>row.after===after).length;assert.equal(restored.split(after).length,count+1,'#382 exact citation literal count');restored=restored.split(after).join(before);}assert.equal(restored,prior,'#382 every noncitation sample byte retained');
 assert.deepEqual(Object.keys(value.control_doc).sort(),['file','before','after','before_gzip_base64'].sort());
 assert.deepEqual({file:value.control_doc.file,before:value.control_doc.before,after:value.control_doc.after},SPEC.control_doc);
 assert.equal(hash(readRaw(value.control_doc.file)),SPEC.control_doc.after);assert.equal(value.control_doc.before,null);assert.equal(value.control_doc.before_gzip_base64,null);
 return true;
}
function validate(options){
 const{artifacts,readRaw=read,requestRetentionLayerValue=layer,...rest}=options;
 let inheritedError;try{previous.validate({...rest,artifacts:predecessorArtifacts(artifacts,requestRetentionLayerValue),readRaw:file=>predecessorRead(readRaw,file,requestRetentionLayerValue)});}catch(error){inheritedError=error;}
 try{validateOwn({artifacts,readRaw,value:requestRetentionLayerValue});}catch(error){if(inheritedError)throw inheritedError;throw error;}
 if(inheritedError)throw inheritedError;return true;
}
function after(kind,key,prior,attr=false){const before=previous.after(kind,key,prior,attr),row=kind==='surfaces'?SPEC.surfaces[key]:SPEC.files[key];if(!row)return before;assert.equal(before,row[attr?'attributed_before':'before'],'#382 exact chained prior '+key);return row[attr?'attributed_after':'after'];}
function sampleAfter(pointer,prior){const before=previous.sampleAfter(pointer,prior),row=SPEC.samples.nodes.find(row=>row.pointer===pointer||row.pointer===pointer+'/source/sha256');if(!row)return before;assert.equal(before,row.before);return row.after;}
function projectGolden(golden){const prior=previous.projectGolden(golden);return{...prior,surfaces:prior.surfaces.map(row=>{const pin=SPEC.surfaces[row.source_id];if(!pin)return row;assert.equal(row.sha256,pin.before);return{...row,sha256:pin.after};})};}
function previousSamples(text){assert.equal(hash(text),SPEC.files[SPEC.samples.file].after);return previous.previousSamples(predecessorRead(()=>Buffer.from(text),SPEC.samples.file).toString('utf8'));}
function readme(old){return previous.readme(old)+'\n'+read(SPEC.control_doc.file).toString('utf8');}
module.exports={...previous,previousRegistry,readme,requestRetentionLayer:layer,requestRetentionSources:Object.keys(SPEC.files),validate,after,sampleAfter,projectGolden,previousSamples};
